namespace sv_e8a77f46f7f84ca6afe8a9a85139f35c.Models;

public sealed class Recipe
{
    public int Id { get; init; }
    public required string Title { get; init; }
    public required string Description { get; init; }
    public int PrepTimeMinutes { get; init; }
}

using sv_e8a77f46f7f84ca6afe8a9a85139f35c.Models;

namespace sv_e8a77f46f7f84ca6afe8a9a85139f35c.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> SeedData = new()
    {
        [1] = new List<Recipe>
        {
            new() { Id = 1, Title = "Margherita Pizza", Description = "Classic Italian pizza with tomato, mozzarella, and basil.", PrepTimeMinutes = 30 },
            new() { Id = 2, Title = "Spaghetti Carbonara", Description = "Creamy pasta with pancetta, egg, and Parmesan cheese.", PrepTimeMinutes = 25 },
            new() { Id = 3, Title = "Tiramisu", Description = "Layered coffee-flavored dessert with mascarpone cream.", PrepTimeMinutes = 45 },
        },
        [2] = new List<Recipe>
        {
            new() { Id = 4, Title = "Tacos al Pastor", Description = "Marinated pork tacos with pineapple and cilantro.", PrepTimeMinutes = 40 },
            new() { Id = 5, Title = "Guacamole", Description = "Fresh avocado dip with lime, onion, and jalapeño.", PrepTimeMinutes = 10 },
            new() { Id = 6, Title = "Churros", Description = "Fried dough pastry coated in cinnamon sugar.", PrepTimeMinutes = 35 },
        },
        [3] = new List<Recipe>
        {
            new() { Id = 7, Title = "Pad Thai", Description = "Stir-fried rice noodles with shrimp, peanuts, and tamarind sauce.", PrepTimeMinutes = 30 },
            new() { Id = 8, Title = "Green Curry", Description = "Aromatic coconut curry with vegetables and Thai basil.", PrepTimeMinutes = 35 },
            new() { Id = 9, Title = "Mango Sticky Rice", Description = "Sweet sticky rice topped with fresh mango and coconut cream.", PrepTimeMinutes = 50 },
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        // Simulate a slow API call.
        await Task.Delay(2000, cancellationToken);

        if (SeedData.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@using sv_e8a77f46f7f84ca6afe8a9a85139f35c.Models
@using sv_e8a77f46f7f84ca6afe8a9a85139f35c.Services
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@implements IDisposable

<PageTitle>Recipes</PageTitle>

<h1>Recipes — Cuisine @CuisineId</h1>

<div class="mb-3">
    <label class="form-label fw-bold">Sort by:</label>
    <a href="/recipes/@CuisineId?sort=newest"
       class="btn btn-sm @(Sort == "newest" ? "btn-primary" : "btn-outline-primary") me-1">
        Newest
    </a>
    <a href="/recipes/@CuisineId?sort=popular"
       class="btn btn-sm @(Sort == "popular" ? "btn-primary" : "btn-outline-primary")">
        Popular
    </a>
</div>

@if (_errorMessage is not null)
{
    <div class="alert alert-danger d-flex align-items-center justify-content-between" role="alert">
        <span>@_errorMessage</span>
        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="RetryAsync">Retry</button>
    </div>
}

@if (_recipes is null && _errorMessage is null)
{
    <div class="d-flex align-items-center gap-2 my-4">
        <div class="spinner-border spinner-border-sm" role="status"></div>
        <span>Loading recipes…</span>
    </div>
}
else if (_recipes is not null)
{
    @if (_isRefreshing)
    {
        <div class="d-flex align-items-center gap-2 mb-3 text-muted">
            <div class="spinner-border spinner-border-sm" role="status"></div>
            <small>Refreshing…</small>
        </div>
    }

    @if (SortedRecipes.Count == 0)
    {
        <p class="text-muted">No recipes found for this cuisine.</p>
    }
    else
    {
        <div class="row row-cols-1 row-cols-md-3 g-3">
            @foreach (var recipe in SortedRecipes)
            {
                <div class="col">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text">@recipe.Description</p>
                        </div>
                        <div class="card-footer text-muted">
                            <small>Prep time: @recipe.PrepTimeMinutes min</small>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private bool _isRefreshing;
    private string? _errorMessage;
    private int _loadedCuisineId;
    private CancellationTokenSource? _cts;

    private List<Recipe> SortedRecipes
    {
        get
        {
            if (_recipes is null) return new();
            return Sort?.ToLowerInvariant() == "popular"
                ? _recipes.OrderByDescending(r => r.PrepTimeMinutes).ToList()
                : _recipes.OrderBy(r => r.Id).ToList();
        }
    }

    protected override async Task OnParametersSetAsync()
    {
        if (CuisineId == _loadedCuisineId)
        {
            // Only the sort parameter changed — no reload needed.
            return;
        }

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request for a previous cuisine.
        await CancelPendingRequestAsync();
        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        _errorMessage = null;
        _isRefreshing = _recipes is not null;

        try
        {
            var result = await RecipeService.GetByCuisineAsync(CuisineId, token);

            // Guard against a stale completion after cancellation.
            if (token.IsCancellationRequested) return;

            _recipes = result;
            _loadedCuisineId = CuisineId;
        }
        catch (OperationCanceledException) when (token.IsCancellationRequested)
        {
            // Request was intentionally cancelled — nothing to do.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            _isRefreshing = false;
        }
    }

    private async Task RetryAsync()
    {
        await LoadRecipesAsync();
    }

    private async Task CancelPendingRequestAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }
}

